content.text:
{
  "name": "crap4js",
  "version": "0.15.0",
  "description": "CRAP (Change Risk Anti-Patterns) metric for JavaScript — combines cyclomatic complexity with Istanbul coverage. A port of crap4java.",
  "type": "module",
  "main": "src/analyzer.js",
  "bin": {
    "crap4js": "./src/cli.js"
  },
  "scripts": {
    "test": "node --test"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@babel/parser": "^8.0.4"
  },
  "devDependencies": {
    "c8": "^12.0.0"
  },
  "keywords": [
    "crap",
    "crap4java",
    "cyclomatic-complexity",
    "coverage",
    "istanbul",
    "quality",
    "metrics"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
