const FAIL = Symbol('fail');

function main(argv, streams = {}) {
  const ctx = context(streams);

  const sub = dispatchSubcommand(argv, ctx);
  if (sub !== null) return sub;

  const opts = tryStep(ctx, () => parseArgs(argv));
  if (opts === FAIL) {
    ctx.out.write(usage());
    return 1;
  }
  if (opts.help) {
    ctx.out.write(usage());
    return 0;
  }
  return runWithOpts(opts, ctx);
}

// Runs the subcommand named by argv[0] when there is one; returns null when
// the first argument is a flag/path and the analyze path should take over.
function dispatchSubcommand(argv, ctx) {
  const run = SUBCOMMANDS[argv[0]];
  if (!run) return null;
  const code = tryStep(ctx, () => run(argv.slice(1), ctx));
  return code === FAIL ? 1 : code;
}

function runWithOpts(opts, ctx) {
  if (opts.runTests && tryStep(ctx, () => runTests(ctx.cwd)) === FAIL) return 1;
  const files = tryStep(ctx, () => resolveFiles(opts, ctx.cwd));
  if (files === FAIL) return 1;
  if (files.length === 0) {
    ctx.out.write('No JavaScript files to analyze.\n');
    return 0;
  }
  const coveragePath = resolveCoveragePath(opts, ctx.cwd);
  const result = tryStep(ctx, () =>
    analyze({ filePaths: files, coveragePath, projectRoot: ctx.cwd, metric: opts.metricValue }),
  );
  if (result === FAIL) return 1;
  const { metrics, parseFailures } = result;
  ctx.out.write(
    formatReport(metrics, {
      threshold: opts.thresholdValue,
      parseFailures,
      metric: opts.metricValue,
    }),
  );
  if (opts.baseline) return baselineVerdict(metrics, opts, ctx);
  return reportVerdict(metrics, opts.thresholdValue, ctx);
}

// Ratchet mode: per-function comparison replaces the max-CRAP threshold for
// known functions; the threshold still applies to functions the baseline
// has never seen. --write-baseline records the current state and passes.
function baselineVerdict(metrics, opts, ctx) {
  const file = path.resolve(ctx.cwd, opts.baseline);
  if (opts.writeBaseline) {
    const doc = buildBaseline(metrics);
    writeBaseline(file, doc);
    ctx.out.write(`Baseline written: ${opts.baseline} (${Object.keys(doc.functions).length} functions, max ${doc.maxCrap})\n`);
    return 0;
  }
  const baseline = tryStep(ctx, () => readBaseline(file));
  if (baseline === FAIL) return 1;
  const result = compareBaseline(metrics, baseline, opts.thresholdValue);
  ctx.out.write(formatComparison(result, opts.thresholdValue));
  if (result.regressions.length || result.newOverThreshold.length) {
    ctx.err.write('CRAP ratchet failed: CRAP may only decrease.\n');

